// Character-only import merges by character ID, then by name.
const characterDialog=document.createElement('dialog');characterDialog.innerHTML='<div class="modal-head"><h2>导入角色信息</h2><button id="closeCharacterImport">✕</button></div><p>支持单个角色、角色数组，或包含 characters / story.main_characters 的 JSON。</p><label class="drop">选择角色 JSON 文件<input id="characterFile" type="file" accept=".json,application/json" hidden></label><textarea id="characterJson" rows="10" placeholder=\'{"characters":[{"character_id":"X07","name":"小七","role":"主角","description":"角色外貌与性格","front_prompt":"正面图提示词","multiview_prompt":"多面图提示词"}]}\'></textarea><p class="subtle">相同 ID 或姓名更新现有角色；新角色加入列表。剧情和分镜保留，已生成版本保留。</p><p id="characterImportStatus" role="status"></p><div class="modal-actions"><button id="previewCharacters">检查角色</button><button id="applyCharacters" class="primary">导入角色</button></div>';document.body.append(characterDialog);
document.querySelector('#closeCharacterImport').onclick=()=>characterDialog.close();
function parseCharacterImport(){let textValue=document.querySelector('#characterJson').value.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');let raw=JSON.parse(textValue),list;if(Array.isArray(raw))list=raw;else if(raw&&typeof raw==='object'){if(raw.project_id&&data.project_id&&raw.project_id!==data.project_id)throw Error('角色文件的 project_id 与当前项目不同');list=raw.characters??raw.roles??raw.story?.main_characters??raw.project?.characters??(raw.character?[raw.character]:raw.name?[raw]:undefined)}if(!Array.isArray(list)||!list.length)throw Error('未找到角色，请提供角色对象或非空 characters 数组');if(list.some(c=>!c||typeof c!=='object'||Array.isArray(c)||!String(c.name||c.character_name||'').trim()))throw Error('每个角色都需要 name 或 character_name');const seen=new Set();for(const c of list){const k=c.character_id||c.id||c.name||c.character_name;if(seen.has(k))throw Error('文件中存在重复角色：'+k);seen.add(k)}const mapped=list.map(c=>({...c,prompt:c.prompt||c.front_prompt||c.prompts?.front||c.prompts?.front_image||c.image_prompts?.front||c.generation?.positive_prompt||c.prompt_anchor_zh,multiPrompt:c.multiPrompt||c.multiview_prompt||c.prompts?.multiview||c.image_prompts?.multiview}));return{library:Array.isArray(raw)?null:raw,raw:list,characters:FrameJSON.parse({type:'characters',characters:mapped}).characters};}
function showCharacterCheck(){const parsed=parseCharacterImport();let existing=0;parsed.characters.forEach((c,i)=>{const raw=parsed.raw[i],id=raw.character_id||raw.id;if(data.characters.some(old=>(id&&old.id===id)||old.name===c.name))existing++});document.querySelector('#characterImportStatus').textContent='识别 '+parsed.characters.length+' 位角色：'+parsed.characters.map(c=>c.name).join('、')+'。将更新 '+existing+' 位，新增 '+(parsed.characters.length-existing)+' 位。';return parsed;}
document.querySelector('#previewCharacters').onclick=()=>{try{showCharacterCheck();document.querySelector('#characterImportStatus').textContent+=' 点击「导入角色」完成保存。'}catch(e){document.querySelector('#characterImportStatus').textContent='检查失败：'+e.message}};
document.querySelector('#characterFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;document.querySelector('#characterImportStatus').textContent='正在读取 '+f.name+'…';if(f.size>5*1024*1024)throw Error('角色文件请小于 5 MB');document.querySelector('#characterJson').value=await f.text();showCharacterCheck()}catch(e){document.querySelector('#characterImportStatus').textContent=e.message}};
document.querySelector('#applyCharacters').onclick=()=>{try{const parsed=showCharacterCheck(),next=clone(data);let first=-1;parsed.characters.forEach((c,i)=>{const raw=parsed.raw[i],id=raw.character_id||raw.id;const index=next.characters.findIndex(old=>(id&&old.id===id)||old.name===c.name);if(index<0){if(!id)c.id='character_'+Date.now()+'_'+i;next.characters.push(c);if(first<0)first=next.characters.length-1}else{const old=next.characters[index];const merged={...old,...c,id:id||old.id,versions:old.versions||[],multi:old.multi||[],confirmed:old.confirmed||false};if(!raw.role&&!raw.story_role&&!raw.identity)merged.role=old.role;if(!c.description)merged.description=old.description;if(!c.prompt)merged.prompt=old.prompt;if(!c.multiPrompt)merged.multiPrompt=old.multiPrompt;next.characters[index]=merged;if(first<0)first=index}});if(parsed.library){for(const field of ['relationships','global_consistency'])if(parsed.library[field]!==undefined)next[field]=clone(parsed.library[field]);next.character_library_version=parsed.library.version||next.character_library_version;}delete next.deleted;localStorage.setItem(key,JSON.stringify(next));data=next;ci=Math.max(0,first);tab=0;characterDialog.close();render();toast('角色信息已导入，已有形象版本已保留')}catch(e){document.querySelector('#characterImportStatus').textContent='导入未完成：'+e.message}};
const charactersBeforeImport=characters;
characters=function(){charactersBeforeImport();const button=document.createElement('button');button.textContent='↓ 导入角色 JSON';button.id='importCharacterButton';button.onclick=()=>{document.querySelector('#characterImportStatus').textContent='';characterDialog.showModal()};const head=document.querySelector('#panel .section-head');if(head){const actions=document.createElement('div');actions.style.cssText='display:flex;gap:8px;flex-wrap:wrap';const add=document.querySelector('#add');if(add)actions.append(add);actions.prepend(button);head.append(actions)}else{document.querySelector('#panel').prepend(button)}};
render();
